pages=[('arena','竞技场'),('story','主线'),('storage','仓库'),('hatch','孵蛋')]
css=(S/'navigation.css').read_text()
def nav(page):return '<header class="final-nav"><div class="brand">BALLS</div><nav>'+''.join(f'<button class="'+('selected' if k==page else '')+f'" data-page="{k}">{t}</button>' for k,t in pages)+'</nav></header>'
for page,title in pages:
 if page in ['arena','story']:
  root=E.parse(S/'input'/(page+'.svg')).getroot()
